import subprocess

def check_imagemagick_support():
    try:
        result = subprocess.run(['convert', '-version'], capture_output=True, text=True, check=True)
        print(result.stdout)
    except subprocess.CalledProcessError as e:
        print(f"ImageMagick is not installed or not functioning properly: {e}")

check_imagemagick_support()
